const requiredTags = 2; // <--- 修改這裡：設定要求的標記人數

const filteredItems = [];

for (const item of $items) {
  const commentText = item.json.text || '';
  // 計算 '@' 符號的數量
  const tagCount = (commentText.match(/@/g) || []).length;

  if (tagCount >= requiredTags) {
    filteredItems.push(item);
  }
}

return filteredItems;

const numberOfWinners = 3; // <--- 修改這裡：設定中獎人數

const participants = $items.map(item => item.json);

if (participants.length === 0) {
  return [{ json: { error: '沒有任何合格的抽獎者！' }}];
}

// Fisher-Yates shuffle algorithm (洗牌演算法)
for (let i = participants.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [participants[i], participants[j]] = [participants[j], participants[i]];
}

const winners = participants.slice(0, numberOfWinners);

return [{ json: { winners: winners, winnerCount: winners.length } }];

